If there are multiple filters targeting the same `fieldPath`, this logic overwrites the previous condition (last filter wins), which will produce incorrect filtering. A concrete approach is to build an `$and` array of per-filter expressions (or merge operators onto the same field where safe) and emit `$match: { $and: [...] }` when needed.
```suggestion
      const andConditions: Record<string, any>[] = [];
      for (const filter of query.filters) {
        const mongoOp = this.convertOperatorToMongo(filter.operator);
        const fieldPath = this.resolveFieldPath(cube, filter.member);
        const condition: Record<string, any> = {};

        if (filter.values && filter.values.length > 0) {
          if (mongoOp === '$in') {
            condition[fieldPath] = { $in: filter.values };
          } else if (mongoOp === '$nin') {
            condition[fieldPath] = { $nin: filter.values };
          } else {
            condition[fieldPath] = { [mongoOp]: filter.values[0] };
          }
        } else if (mongoOp === '$exists') {
          condition[fieldPath] = { $exists: filter.operator === 'set' };
        }

        if (Object.keys(condition).length > 0) {
          andConditions.push(condition);
        }
      }
      if (andConditions.length === 1) {
        pipeline.push({ $match: andConditions[0] });
      } else if (andConditions.length > 1) {
        pipeline.push({ $match: { $and: andConditions } });
